158	    /**
159	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
160	     * upper-cases the value, and expands common street-type abbreviations word-by-word
161	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
162	     * normalizes to the empty string. The normalized value is what the application stores, returns
163	     * and compares for household detection.
164	     *
165	     * @param address the raw address value from the request, may be {@code null}
166	     * @return the normalized address, or the empty string when none was supplied
167	     */
168	    private String normalizeAddress(String address) {
169	        if (address == null) {
170	            return "";
171	        }
172	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
173	        if (collapsed.isEmpty()) {
174	            return "";
175	        }
176	        String[] tokens = collapsed.split(" ");
177	        StringBuilder normalized = new StringBuilder();
178	        for (int i = 0; i < tokens.length; i++) {
179	            if (i > 0) {
180	                normalized.append(' ');
181	            }
182	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
183	        }
184	        return normalized.toString();
185	    }
186	
187	    /**
188	     * Rejects an owner payload that is missing or blank in any required field. The response body's
189	     * {@code errors} array lists the name of each offending field.
190	     *
191	     * @param ownerFieldsDto the owner payload to validate
192	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
193	     */
194	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
195	        List<String> missingFields = new ArrayList<>();
196	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
197	            missingFields.add("firstName");
198	        }
199	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
200	            missingFields.add("lastName");
201	        }
202	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
203	            missingFields.add("address");
204	        }
205	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
206	            missingFields.add("city");
207	        }
208	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
209	            missingFields.add("telephone");
210	        }
211	        if (!missingFields.isEmpty()) {
212	            throw new RequiredFieldsMissingException(missingFields);
213	        }
214	    }
215	
216	    /**
217	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
218	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
219	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
220	     * followed by 8 to 15 digits.
221	     *
222	     * @param telephone the raw telephone value from the request
223	     * @return the E.164 telephone (e.g. {@code +61412345678})
224	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
225	     */
226	    private String normalizeTelephone(String telephone) {
227	        if (telephone == null) {
228	            throw new InvalidFieldsException(List.of("telephone"));
229	        }
230	        String trimmed = telephone.trim();
231	        boolean international = trimmed.startsWith("+");
232	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
233	        String digits;
234	        if (international) {
235	            digits = cleaned.substring(1);
236	        } else {
237	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
238	            digits = "61" + national;
239	        }
240	        if (!digits.matches("[0-9]{8,15}")) {
241	            throw new InvalidFieldsException(List.of("telephone"));
242	        }
243	        requireValidNationalLength(digits);
244	        return "+" + digits;
245	    }
246	
247	    /**
248	     * Country codes with a fixed national-number length, checked longest-prefix first so that
249	     * '+61' is matched before the '+1' prefix it starts with. Australia ('61') requires 9 national
250	     * digits; the North American Numbering Plan ('1') requires 10.
251	     */
252	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
253	
254	    /**
255	     * Validates that the national number (the E.164 digits after the country code) has the length
256	     * required for its country. Country codes without a known fixed length are left to the general
257	     * E.164 length check.
258	     *
259	     * @param digits the E.164 digits (country code plus national number, without the leading '+')
260	     * @throws InvalidFieldsException if the national number is the wrong length for its country
261	     */
262	    private void requireValidNationalLength(String digits) {
263	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
264	            .filter(entry -> digits.startsWith(entry.getKey()))
265	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
266	            .ifPresent(entry -> {
267	                int nationalLength = digits.length() - entry.getKey().length();
268	                if (nationalLength != entry.getValue()) {
269	                    throw new InvalidFieldsException(List.of("telephone"));
270	                }
271	            });
272	    }
273	
274	    /**
275	     * Best-effort normalization of an existing owner's stored telephone into E.164 form for
276	     * duplicate comparison, returning {@code null} when the value cannot form valid E.164.
277	     *
278	     * @param telephone an existing stored telephone value, may be {@code null}
279	     * @return the E.164 form, or {@code null} when it cannot be normalized
280	     */
281	    private String toE164OrNull(String telephone) {
282	        if (telephone == null) {
283	            return null;
284	        }
285	        try {
286	            return normalizeTelephone(telephone);
287	        }
288	        catch (InvalidFieldsException ex) {
289	            return null;
290	        }
291	    }
292	
293	    /**
294	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
295	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
296	     * be a syntactically valid address; the accepted value is returned lower-cased.
297	     *
298	     * @param email the raw email value from the request, may be {@code null}
299	     * @return the lower-cased email, or {@code null} when none was supplied
300	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
301	     */
302	    private String normalizeEmail(String email) {
303	        if (email == null || email.isBlank()) {
304	            return null;
305	        }
306	        String trimmed = email.trim();
307	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
308	            throw new InvalidFieldsException(List.of("email"));
309	        }
310	        return trimmed.toLowerCase(Locale.ROOT);
311	    }
312	
313	    /**
314	     * Rejects an email that, compared case-insensitively, is already used by any existing owner.
315	     * Existing owners' emails are lower-cased before comparison so that addresses differing only in
316	     * letter case are treated as duplicates. A {@code null} email (none supplied) is never a
317	     * duplicate.
318	     *
319	     * @param email the normalized (lower-cased) email of the owner being created, may be {@code null}
320	     * @throws DuplicateOwnerEmailException if another owner already uses the email
321	     */
322	    private void requireUniqueEmail(String email) {
323	        if (email == null) {
324	            return;
325	        }
326	        boolean taken = this.clinicService.findAllOwners().stream()
327	            .map(Owner::getEmail)
328	            .filter(existing -> existing != null)
329	            .map(existing -> existing.toLowerCase(Locale.ROOT))
330	            .anyMatch(email::equals);
331	        if (taken) {
332	            throw new DuplicateOwnerEmailException(email);
333	        }
334	    }
335	
336	    /**
337	     * Rejects a telephone that, once normalized, is already used by any existing owner. Existing
338	     * owners' telephones are normalized the same way before comparison so differently-formatted
339	     * values representing the same number are treated as duplicates.
340	     *
341	     * @param telephone the normalized (E.164) telephone of the owner being created
342	     * @throws DuplicateOwnerTelephoneException if another owner already uses the telephone
343	     */
344	    private void requireUniqueTelephone(String telephone) {
345	        boolean taken = this.clinicService.findAllOwners().stream()
346	            .map(Owner::getTelephone)
347	            .map(this::toE164OrNull)
348	            .filter(existing -> existing != null)
349	            .anyMatch(telephone::equals);
350	        if (taken) {
351	            throw new DuplicateOwnerTelephoneException(telephone);
352	        }
353	    }
354	
355	    /**
356	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
357	     * fields (last name, address) can be compared case-insensitively with collapsed whitespace. A
358	     * {@code null} value normalizes to the empty string.
359	     *
360	     * @param value the raw field value, may be {@code null}
361	     * @return the trimmed, whitespace-collapsed, lower-cased form
362	     */
363	    private String normalizeHousehold(String value) {
364	        if (value == null) {
365	            return "";
366	        }
367	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
368	    }
369	
370	    /**
371	     * Rejects an owner whose last name and address already match another owner (compared
372	     * case-insensitively with collapsed whitespace) - i.e. they would share a household - unless the
373	     * request opts in via {@code sharesHousehold}. Existing owners' fields are normalized the same
374	     * way before comparison.
375	     *
376	     * @param lastName the last name of the owner being created
377	     * @param address the address of the owner being created
378	     * @throws DuplicateOwnerHouseholdException if another owner shares the household
379	     */
380	    private void requireUniqueHousehold(String lastName, String address) {
381	        String normalizedLastName = normalizeHousehold(lastName);
382	        String normalizedAddress = normalizeHousehold(address);
383	        boolean shared = this.clinicService.findAllOwners().stream()
384	            .anyMatch(existing -> normalizeHousehold(existing.getLastName()).equals(normalizedLastName)
385	                && normalizeHousehold(existing.getAddress()).equals(normalizedAddress));
386	        if (shared) {
387	            throw new DuplicateOwnerHouseholdException(lastName, address);
388	        }
389	    }
390	
391	    /**
392	     * Rejects an owner whose city already contains the maximum permitted number of owners
393	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
394	     * the same normalization used for the other owner household fields.
395	     *
396	     * @param city the city of the owner being created
397	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
398	     */
399	    private void requireCityHasCapacity(String city) {
400	        String normalizedCity = normalizeHousehold(city);
401	        long count = this.clinicService.findAllOwners().stream()
402	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
403	            .count();
404	        if (count >= CITY_CAPACITY) {
405	            throw new CityAtCapacityException(city);
406	        }
407	    }
408	
409	    /**
410	     * Rejects creating an owner once the given business day has already reached the maximum
411	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
412	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
413	     * registration date.
414	     *
415	     * @param registrationDate the business-day-adjusted registration date of the owner being created
416	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
417	     *     registered on that business day
418	     */
419	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
420	        long count = this.clinicService.findAllOwners().stream()
421	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
422	            .count();
423	        if (count >= DAILY_OWNER_LIMIT) {
424	            throw new DailyOwnerLimitException(registrationDate);
425	        }
426	    }
427	
428	    /**
429	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
430	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
431	     * been registered on that date. Evaluated before the new owner is persisted, so the count
432	     * reflects the owners that existed at the time of creation.
433	     *
434	     * @param registrationDate the business-day-adjusted registration date of the owner being created
435	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
436	     *     that registration date, otherwise {@code false}
437	     */
438	    private boolean isBulkSignup(LocalDate registrationDate) {
439	        long count = this.clinicService.findAllOwners().stream()
440	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
441	            .count();
442	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
443	    }
444	
445	    /**
446	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced to the
447	     * following Monday, while a weekday is returned unchanged.
448	     *
449	     * @param date the effective registration date (supplied or defaulted to the server date)
450	     * @return the same date when it is a weekday, otherwise the next Monday
451	     */
452	    private LocalDate toBusinessDay(LocalDate date) {
453	        return switch (date.getDayOfWeek()) {
454	            case SATURDAY -> date.plusDays(2);
455	            case SUNDAY -> date.plusDays(1);
456	            default -> date;
457	        };
458	    }
