package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when an owner is created whose derived identity key
 * ({@code normalizedTelephone|email|householdId}) is already used by another owner. This single
 * key consolidates the former separate telephone, email and household duplicate checks.
 * <p>
 * The exception handler reports this as a 409 Conflict, since the request collides with the current
 * state of an existing resource.
 */
public class DuplicateOwnerIdentityException extends RuntimeException {

    private final String identityKey;

    public DuplicateOwnerIdentityException(String identityKey) {
        super("An owner with identity key '" + identityKey + "' already exists");
        this.identityKey = identityKey;
    }

    public String getIdentityKey() {
        return this.identityKey;
    }
}

